import { useState } from "react";
import { Navigate } from "react-router-dom";

/**
 * routerでページ遷移をする際に判定をして、trueの時はredirectComponentに、falseの時は別のページへアクセスします。
 * @param {any} judgElement 
 * @param {any} RedirectComponent 
 * @param {string} redirectPath 
 * @returns 
 */
export default async function RouteCheck(
    judgElement,
    RedirectComponent,
    redirectPath
) {
    const [isResult, setResult] = useState(true);

    useEffect(() => {
        async function fetchData() {
            const result = await judgElement();
            setResult(result);
        }

        fetchData();
    }, judgElement);

    return result ? <RedirectComponent /> : <Navigate to={redirectPath} />;
}


